<?php defined('BASEPATH') OR exit('No direct script access allowed');class Billing_model extends CI_Model{private $plans=array('starter'=>array('Starter',0,0,5,0,0),'pro'=>array('Pro',2900,29000,1,1200,12000),'team'=>array('Team',9900,99000,5,1500,15000),'enterprise'=>array('Enterprise',0,0,10,0,0));function __construct(){parent::__construct();$this->load->database();}function subscription($org){$r=$this->db->where('organization_id',$org)->get('billing_subscriptions')->row_array();if(!$r){$now=date('Y-m-d H:i:s');$r=array('id'=>$this->uuid(),'organization_id'=>$org,'plan'=>'starter','status'=>'active','seats'=>5,'cycle'=>'monthly','current_period_start'=>$now,'current_period_end'=>date('Y-m-d H:i:s',strtotime('+1 month')),'created_at'=>$now,'updated_at'=>$now);$this->db->insert('billing_subscriptions',$r);}return $r;}function overview($org){$s=$this->subscription($org);$p=$this->plans[$s['plan']];$sub=array('id'=>$s['id'],'plan'=>$s['plan'],'planName'=>$p[0],'status'=>$s['status'],'seats'=>(int)$s['seats'],'cycle'=>$s['cycle'],'currentPeriodStart'=>$s['current_period_start'],'currentPeriodEnd'=>$s['current_period_end'],'customerEmail'=>$s['customer_email']??NULL,'monthlyRate'=>$p[1],'renewalCents'=>$s['cycle']==='annual'?$p[2]:$p[1]);$plans=array();foreach($this->plans as $id=>$v)$plans[]=array('id'=>$id,'name'=>$v[0],'monthly'=>$v[1],'annual'=>$v[2],'seatIncluded'=>$v[3],'perSeatMonthly'=>$v[4],'perSeatAnnual'=>$v[5]);$rows=$this->db->where('organization_id',$org)->order_by('created_at','DESC')->get('invoices')->result_array();$inv=array_map(array($this,'invoice_view'),$rows);$open=0;$sum=0;foreach($rows as $r)if(in_array($r['status'],array('open','overdue'),TRUE)){$open++;$sum+=(int)$r['amount_cents'];}return array('subscription'=>$sub,'plans'=>$plans,'invoices'=>$inv,'accountsReceivable'=>array('openInvoiceCount'=>$open,'openInvoiceTotal'=>$sum));}function update_sub($org,$d){$s=$this->subscription($org);$set=array('updated_at'=>date('Y-m-d H:i:s'));foreach(array('plan','seats','cycle') as $f)if(isset($d[$f]))$set[$f]=$d[$f];if(isset($d['customerEmail']))$set['customer_email']=$d['customerEmail'];$this->db->where('id',$s['id'])->update('billing_subscriptions',$set);return $this->overview($org)['subscription'];}function invoice_action($id,$org,$status,$reason=NULL){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('invoices')->row_array();if(!$r)return NULL;$set=array('status'=>$status,'updated_at'=>date('Y-m-d H:i:s'));if($status==='paid')$set['paid_at']=date('Y-m-d H:i:s');if($status==='void')$set['void_reason']=$reason;$this->db->where('id',$id)->update('invoices',$set);return $this->invoice_view(array_merge($r,$set));}function payment($d){$old=$this->db->where('event_id',$d['eventId'])->get('payment_records')->row_array();if($old)return array('idempotent'=>TRUE,'applied'=>FALSE);$inv=$this->db->where('number',$d['invoiceNumber'])->get('invoices')->row_array();$this->db->insert('payment_records',array('id'=>$this->uuid(),'event_id'=>$d['eventId'],'invoice_id'=>$inv['id']??NULL,'status'=>$d['status'],'amount_cents'=>$d['amountCents']??NULL,'currency'=>strtoupper($d['currency']??'USD'),'meta'=>json_encode($d['meta']??array()),'created_at'=>date('Y-m-d H:i:s')));if($inv)$this->invoice_action($inv['id'],$inv['organization_id'],$d['status']==='paid'?'paid':$d['status']);return array('idempotent'=>FALSE,'applied'=>(bool)$inv);}function invoice_view($r){return array('id'=>$r['id'],'number'=>$r['number'],'amountCents'=>(int)$r['amount_cents'],'currency'=>$r['currency'],'status'=>$r['status'],'dueDate'=>$r['due_date'],'paidAt'=>$r['paid_at'],'hostedUrl'=>$r['hosted_url'],'pdfUrl'=>$r['pdf_url'],'createdAt'=>$r['created_at'],'lines'=>json_decode($r['lines'],TRUE)?:array());}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
